    "question": "2023年3月に策定された「生物多様性国家戦略2023-2030」（以下、「国家戦略2023-2030」という。）に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．生物多様性国家戦略は、生物の多様性の保全及び持続可能な利用に関する施策の総合的かつ計画的な推進を図ることを目的として、自然環境保全法に基づき策定される戦略である。当該国家戦略は、環境大臣、農林水産大臣及び国土交通大臣が、自然再生専門家会議の意見を聴取した上で、決定することとされている。\n\nB．国家戦略2023-2030では、2050年ビジョン「自然との共生」の達成に向けて、「2030年までに、『ネイチャーポジティブ：自然再興』を実現する。」との短期目標（2030年ミッション）が掲げられている。国家戦略2023-2030において、ネイチャーポジティブとは、「自然を回復軌道に乗せるため、生物多様性の損失を止め、反転させること」とされている。\n\nC．国家戦略2023-2030では、2030年までに陸と海の30％以上を保全するとした、いわゆる「30 by 30目標」の達成に向けた取組を進めることとされている。具体的な取組には、国立公園等の保護地域の拡張と管理の質の向上に加え、「保護地域以外で生物多様性保全に資する地域（OECM＊1）」の設定・管理が挙げられている。\n\nD．国家戦略2023-2030では、自然の恵みを活かして、防災・減災や資源循環などの様々な社会課題の解決につなげる「自然を活用した解決策（NbS＊2）」を進めることとされている。具体的な取組として、災害に対してレジリエントな地域を作る「生態系を活用した防災・減災（Eco-DRR＊3）」の実装の推進などが挙げられている。\n\n＊1 Other Effective area-based Conservation Measures\n＊2 Nature-based Solutions\n＊3 Ecosystem-based Disaster Risk Reduction",
