      "エ": "平成30（2018）年の木材流通構造調査によると、製材工場で生産された木材製品のうち、約6割が住宅メーカーや工務店等に直接出荷され、残りの約4割がプレカット工場に出荷されている。プレカット加工においては、部材の寸法安定性が求められることから、プレカット工場で使用される材料のほとんどは、天然乾燥材である。",
      "オ": "我が国の人工林から出材する原木については、末口直径が30 cmを超えるような大径材の増加が見込まれている。大径材の製材については、中径材の製材を主とする製材工場の既存の設備でも対応が可能で、複雑な木取りを行うことで中径材よりも生産効率が向上するほか、芯を外した木取りにより乾燥時の反りや曲がりが出にくくなるため、多くの工場で大径材を積極的に製材している。"
