      "イ": "ウメは、中国原産の落葉高木であり、我が国には江戸時代に移入され、全国に広がった。一般に、冬から初春にかけて開花する花は観賞用として、また実は食用として利用される。黄色の花が咲くロウバイはウメの遅咲きの品種の一つである。",
      "ウ": "ツツジ類は、一般に、晩秋から冬にかけて花を咲かせ、季節の風物詩として楽しまれてきたほか、多くの園芸品種が公園や庭園などに利用されている。ツツジ類は、我が国の固有植物であり、我が国で改良された園芸品種が江戸時代に海外に移出され、もともと自生していなかった西欧でオリエンタルな花木として人気を博した。",
      "エ": "ススキは、平地や山地の日当たりの良い場所に普通に見られる一年草であり、ススキを材料に屋根を葺いていたことから刈屋根の意味でカヤとも呼ばれる。セリやナズナとともに、春の七草の一つである。",
      "オ": "レンゲソウ（ゲンゲ）は、中国原産のマメ科の草本であり、春に、主に紅紫色の花をつける。田植え前に水の張っていない田んぼで栽培され、窒素の供給源となる緑肥として利用されてきた。また、ハチミツ用の蜜源植物としても利用されてきた。"
