    "difficulty": 3,
    "question": "次は、人工林の生物多様性に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\nMany tree plantations have been traditionally labelled as “green deserts”, and are presumed to be hostile＊1 to native species and largely devoid＊2 of wildlife. However, closer inspection of available data indicates that while it is certainly true that some intensively managed plantation monocultures offer very little value to biodiversity, other plantation systems can provide valuable species ［A］, even for some threatened and endangered taxa. This apparent contradiction is explained in part by marked differences in the levels of biodiversity that can be supported by different types of plantation. For example, there is a stark contrast in the conservation value of industrial monocultures of exotic species that often have little or no intrinsic value for native forest species, compared with complex multi-species plantations that encompass remnants of native vegetation and are managed as a mosaic of differently aged stands. However, a second reason why many plantations are incorrectly presumed to be biological deserts is that human ［B］ of habitat quality are often distinct from how native species themselves perceive the landscape.\n\n（中略）\n\nThe value of a given plantation forest for conservation is partly determined by how it is managed. For example, at the stand level, many studies have found that faunal＊3 diversity in tree plantations is strongly influenced by the maintenance of ［C］ attributes, such as snags and dead wood, and the tolerance of succession by native plant species in the understorey. More floristically＊4 and structurally complex plantations provide more resources for many forest species (e.g. fruit feeding butterflies). At the landscape scale, spatial heterogeneity in stand management and ［D］ has been shown to be a key factor in determining the overall level of diversity within a given plantation forest.\n\n＊1 hostile：敵対する\n＊2 devoid：欠いている\n＊3 faunal：動物の、動物相の\n＊4 floristically：植物の、植物的な",
