      "ウ": "森林土壌は、A₀層とA層の土壌層位の状態によりモル型、モダー型、ムル型の三つに分類される。モル型は、A₀層もA層も三つの型のうちで最も厚い。また、生息する土壌動物については、ムル型では、モル型と比べてミミズが少なく、トビムシ・ダニが多い。",
