      "イ": "先端への細りが小さい幹を完満、大きいものをうらごけと呼ぶ。T/R率は樹冠と根など地上部と地下部の比に用いられ、幹の各部位の直径の比を指さない。",
      "ウ": "リーケ式は両端と中央の断面積を用いて材積を求める。末口の寸法を使うJASの計算式とは異なる。",
