    "question": "我が国の木材搬出の歴史に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．機械が出現する以前の木材の搬出は、山中では、玉切りした木材を木馬と呼ばれる橇、牛馬や荷車などの人畜力、丸太を並べて滑路とした修羅などによって行われていた。また、河川では、管流し、鉄砲堰、筏流しなどの水運が行われていた。\n\nB．森林鉄道は、明治時代後期より、全国各地の民有林を中心に整備され、現在把握されているもので、全国に約1,250路線、約9,000 kmにも及んだ。明治44（1911）年には満州国に全長約70 km、高低差2,200 m以上の阿里山森林鉄道が完成し、今日でも観光鉄道として活躍している。\n\nC．昭和32（1957）年の国有林生産力増強計画では、木材を大量に輸送するため、奥山への森林鉄道の延長と、老朽化した森林鉄道の軽車道への転換が方針として決定された。そして、昭和48（1973）年の林道規程改正で、林道の種類は軽車道が主となり、森林鉄道、木馬道、流送路は削除された。\n\nD．1960年代後半、ホイスチングキャレッジを使用するダブルエンドレス式索張りが登場した。この索張りは、材を搬器まで引き上げることができることから、索下の植生を傷つけるおそれが小さく、他の所有者の林地を越えなければならないことの多い民有林の作業事情に適合しているため、広く民有林に普及した。",
