    "difficulty": 3,
    "question": "次は、土量の変化率に関する記述であるが、ア～オに当てはまるものの組合せとして最も妥当なのはどれか。\n\n土の体積は、地山の状態（地山の土量）、掘削されてほぐされた状態（ほぐした土量）、締固められた状態（締固め後の土量）で大きく異なり、この土量の変化を地山の土量に対する体積比で表す。これを土量の変化率といい、次式で表す。\nC＝［ア］／地山の土量、L＝［イ］／地山の土量\n\n土量計算を行う際は、掘削すべき切土には［ウ］を用い、盛土には［エ］を用いる。\n\n現場内発生土の土量の変化率が C＝0.80、L＝1.20 のとき、100 m³の盛土を行うため、120 m³の現場発生土（ほぐした土量）を使用した場合、不足土量（地山の土量）は［オ］m³となる。ただし、基礎地盤の沈下などによる土量の損失が無いものとする。",
