      "イ": "明治期には、新政府により招聘されたアメリゴ・ホッフマンなどのイギリス人土木技師により、水源から河口に至るまで水系一貫の河川管理が提唱された。明治7（1874）年には、河川下流域にそだ護岸工を設置する河川工事が木津川で実施されたが、現在は残っていない。",
