    "session": "senmon-shinrin-shizen",
    "qNumber": 43,
    "type": "multiple-choice",
    "category": "砂防学基礎",
    "topicTags": [
      "施設の長寿命化と予防保全",
      "選択問題",
      "砂防学基礎"
    ],
    "difficulty": 3,
    "question": "我が国の公共インフラ、特に砂防関係施設、治山施設の長寿命化に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．我が国では、高度経済成長期以降に集中的に整備されたインフラの老朽化が深刻であり、今後、建設から50年以上経過する施設の割合が加速的に進行する。国民の安全・安心の確保や維持管理・更新に係るトータルコストの縮減・平準化等を図るため、平成25年11月、計画的な維持管理・更新等の方向性を示す基本的な計画である「インフラ長寿命化基本計画」が取りまとめられた。\n\nB．砂防関係施設の長寿命化計画は、既存の砂防関係施設の点検を適切に実施し、健全度を把握することにより、施設被災時の速やかな復旧に資することを目的に作成する。作成に当たって点検結果を踏まえた健全度評価結果を整理する必要があるが、技術の発展に伴い点検の大半は無人航空機（UAV）を用いて効率的に実施しており、目視による点検は行われていない。\n\nC．砂防関係施設、治山施設の維持管理の考え方には、所定の機能及び性能が確保できなくなった段階で一部機能を回復させる修繕や改築等を実施する予防保全と、所定の機能及び性能が確保できなくなった段階で全面更新等を行う予知保全がある。予防保全と予知保全を比べてライフサイクルコストの縮減を図り、少ない予算で実施可能な方法を選択するのが望ましい。\n\nD．長寿命化計画における予防保全の検討に当たっては、各施設・部位の劣化予測を行い、施設の健全度の低下を把握することが重要である。劣化予測は、施設の健全度評価と経過年数との関係により把握するもので、設置されている場の特性に応じて劣化速度が異なることから、場の特性ごとにデータを取りまとめておくことが望ましい。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "A、D",
      "エ": "C、D",
      "オ": "B、C、D"
    },
    "answer": "ウ",
    "officialAnswerNumber": 3,
    "explanation": "2013年の基本計画の目的を述べるAと、設置条件ごとに施設の劣化を予測するDが妥当である。計画的な点検と修繕を通じて施設の機能を保ち、費用の縮減や平準化を図る。",
    "choiceExplanations": {
      "ア": "Aは妥当だがBは誤りである。砂防関係施設の点検では近接目視等が行われ、UAVは現地に近づきにくい場合などに活用される。",
      "イ": "Aは妥当だがCは誤りである。予防保全は所定の機能を失う前に必要な修繕などを行って、機能低下を防ぐ考え方である。",
      "ウ": "2013年の基本計画の目的を述べるAと、設置条件ごとに施設の劣化を予測するDが妥当である。計画的な点検と修繕を通じて施設の機能を保ち、費用の縮減や平準化を図る。",
      "エ": "Dは妥当だがCは誤りである。機能低下が起きてから修繕・更新を行うのは事後保全であり、予防保全とは区別される。",
      "オ": "Dは妥当である。Bは目視点検を行わない点が誤りで、Cは機能喪失後の修繕を予防保全としている点が誤りである。"
    },
