    "question": "次は、我が国でみられる地質構造に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n海洋側のプレートが大陸側のプレートの下に沈み込む際、海洋側のプレートの岩石の一部が大陸縁辺に付け加わったものを付加体といい、我が国では［A］などが挙げられる。\n\n沈み込み境界深部に持ち込まれた、又はマグマ活動の活発な場所での火成岩や堆積岩は、温度や圧力により［B］という特徴的な変成作用を受ける。この作用によってできた岩石として、［C］などがある。\n\n一方、マグマに接した砂岩や泥岩などは、狭い範囲で変成作用が生じることがある。これにより生まれる岩石の一つであるホルンフェルスは、［D］変成岩である。",
