      "イ": "Cは妥当だが、Aは土砂の生産を抑える工種と、流れてくる土砂を捕捉・調節する工種を混同している。山腹工は斜面の侵食や崩壊を抑える工種である。",
      "ウ": "BとCが妥当である。渓流保全工は侵食を防ぎつつ場所に応じて河床の変動を許容し、土砂の流出を抑える施設は保全対象への効果が大きい箇所に配置する。",
      "エ": "Bは妥当だがDは誤りである。遊砂地工では急勾配の上流域より、流速を落として土砂をためられる緩勾配の区間などを選ぶ。",
      "オ": "Cは妥当だがDは誤りである。遊砂地工は土砂を堆積させるため、流路を拡大でき、堆積に適した区間に設ける。"
