    "question": "砂防堰堤に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA．不透過型の重力式コンクリート砂防堰堤の下流のり面は、越流土砂による損傷を極力受けないように設計する。このため、越流部における下流のり面の勾配は、高さと水平距離の比を1：0.2とする。なお、粒径が細かく、中小出水においても土砂流出が少なく、流域面積の小さい渓流では、これよりも緩い勾配とすることができる。\n\nB．土砂調節を目的とする透過型砂防堰堤には、洪水流の堰上げによって、土砂の流出を調節するものがあり、流出土砂量のピークを低減する効果を期待して設置される。ただし、洪水が収まってきた頃などに、砂防堰堤の上流に堆積していた土砂が下流へ流出してしまう場合があることに留意が必要である。\n\nC．重力式コンクリート砂防堰堤の堤体は、土石流の発生時において、その安定を保っていられるようにするため、堤体に作用することが想定される外力に対して、転倒、滑動、堤体材料の最大応力及び地盤支持力のいずれかに安定である条件を満たして設計する。このうち堤体材料の最大応力については、砂防堰堤の底面の上流端に圧縮応力が生じないように設計する。\n\nD．土石流の危険がある渓流では、透過型砂防堰堤による土石流の捕捉が効果的である。透過部材の間隔は、当該渓流の最大礫径の1/2倍程度を基本とし、確実に土石流を捕捉できる構造にすることが望ましい。また、土石流に伴う流木が透過部分をすり抜けることを防ぐため、透過部材の間隔は想定される流木の直径の1～1.5倍程度とし、最大礫径の1/2倍程度と比較して大きい方の値を採用する。",
