    "difficulty": 3,
    "question": "山腹保全工に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA．山腹保全工は、山腹斜面に発生する表面侵食から深層崩壊まで、幅広い土砂移動現象の防止を目的に行われる工事である。このため施工される工種も、斜面の地表水や地下水を排除する山腹排水工、斜面の土砂移動を固定する山腹土留工や遊砂地工、渓流に施工する谷止工や砂防堰堤工など多岐にわたる。\n\nB．表面侵食は、斜面の表層付近で地下水が地中の土粒子を撹乱し、斜面内部の浸透能を減少させることで表面流が発生し、表面流の掃流力により斜面の土粒子が剝離、運搬されることにより発生する。表面侵食による土砂生産を防止するためには、基岩の風化による土粒子の生産を抑制するために、斜面を被覆する対策が必要となる。\n\nC．山腹緑化工に用いられる植物は、生育する環境条件が厳しいことから、木本種では、やせ地に耐える、成長が早く活着しやすい、土の理化学性を改善しうる等の特徴があるものを選ぶ。また、草本種では、やせ地に耐える、成長が早く根茎がよく発達する、再生力が強い等の特徴があるものを選ぶ。\n\nD．山腹斜面に侵食や崩壊がある場合、山腹基礎工や山腹斜面補強工により山腹斜面の土砂の移動を抑えて植生の自然侵入を期待するが、これが期待できない場合には山腹緑化工を行う。このとき、使用する植物種によっては植生遷移を遅らせるなどの弊害となる場合があることに留意する。",
