    "question": "我が国の地すべり防止施設に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．抑止工は、地すべりを防止するために地すべり地に排水施設を設けて、地下水の排除によって地すべり運動を停止させようとする工法であり、地表付近の地下水を暗渠などで集水する浅層地下水排除工、地すべりのすべり面付近の地下水を排水させる深層排水工などがある。\n\nB．集水井工は、地下水が層状などに分布している場合に集中的に集水することを目的とする工法であり、地下水の多い部分に集水井（縦井戸）からの横ボーリングによって付近の地下水を集め、集水井の底部付近から排水ボーリングによって排水するものである。\n\nC．水路工は、地すべり地内の地表水や地すべり地外から流入する地表水を、速やかに地すべり地外に排水するために地表面に水路を設ける工法であり、斜面を横切って地表水を集める集水路工と、集めた水をできるだけ早く地外に排水するため谷地形の箇所に設ける排水路工がある。\n\nD．排土工は、地すべり推力を減少させることを目的に地すべりの中央部から末端域において行われる工法であり、また、盛土工は、地すべり頭部域に盛土することによってせん断力を増加させる工法である。排土工と盛土工は、どちらも地すべり運動を停止させる抑止工の一つである。",
