    "difficulty": 3,
    "question": "コンクリートに関する記述として最も妥当なのはどれか。",
    "choices": {
      "ア": "コンクリートは、硬化が始まり、完了するまでの5～10分間に流動させることができ、様々な形状の型枠に詰めることができる。このような、流動可能な時期や状態のコンクリートを硬化コンクリートという。また、硬化し終わった後の、形状が固定された時期や状態のコンクリートをフレッシュコンクリートという。",
      "イ": "コンクリートの高性能化や産業副産物の有効利用の観点などから、様々な種類の混和材が利用されている。主な混和材には、フライアッシュや膨張材などがある。また、コンクリートの硬化速度や硬化後の性質などを制御するために、混和剤が利用されている。主な混和剤には、AE剤や減水剤などがある。",
      "ウ": "スランプとは、スランプ試験においてコンクリートの上面の下がりを10 cm刻みで測定した値である。スランプは、コンクリートに対して水量が適切であるか、細骨材量が適切であるかを評価することができる指標である。この値が小さければ小さいほど、コンクリートの性質が良好であると評価される。",
      "エ": "コンクリートを構成する材料の体積のおおよその比率は、骨材50％、セメントペースト25％、気泡25％である。コンクリートは空気や液体が出入りできる多孔質な材料であり、水圧を受ければ透水する。透水によるコンクリートの劣化を防ぐため、局所的に空隙を作り、そこから水を逃がすことが有効な手立てである。",
      "オ": "コンクリート強度とは、一般に、コンクリートが硬化し終わってから24時間後の圧縮強度のことである。圧縮強度は、コンクリートが圧縮力で破壊されるまでの作用応力の最大値と定義されており、コンクリートと水の配合割合によってのみ決まる。この施工管理のしやすさから、コンクリートは構造物の材料として多く用いられている。"
    },
    "answer": "イ",
    "officialAnswerNumber": 2,
    "explanation": "フライアッシュなどの混和材は、コンクリートの性質を改善し、副産物の利用にも役立つ。AE剤や減水剤などの混和剤は、施工性や耐久性などを調整する。",
    "choiceExplanations": {
      "ア": "練り混ぜ直後から硬化前の流動性があるコンクリートをフレッシュコンクリートと呼ぶ。強度が発現した後のものを硬化コンクリートと呼ぶ。",
      "イ": "フライアッシュなどの混和材は、コンクリートの性質を改善し、副産物の利用にも役立つ。AE剤や減水剤などの混和剤は、施工性や耐久性などを調整する。",
      "ウ": "スランプは型を外した後の沈下量で、フレッシュコンクリートの流動性の目安になる。測定は10 cm刻みではなく、適切な値は部材や施工方法によって異なる。",
      "エ": "通常のコンクリートでは骨材が体積の大部分を占め、空気量は数％程度である。透水を抑えるには、水セメント比や締固め、養生などを通じて連続した空隙を減らすことが重要である。",
      "オ": "圧縮強度の標準的な指標には一般に材齢28日の試験値を用いる。水セメント比のほか、材料や養生条件なども強度に影響する。"
    },
