    "question": "次は、河川の蛇行に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\nA meander is when water flows in a curvy, bendy path, like a snake. As a river makes its way through an area that is relatively ［A］, it often develops bends as it ［B］ its way through the path of least resistance. Once a meander starts, it often becomes more and more exaggerated. Why is this? Water is pushed to the ［C］ of a bend, and erodes the curve further, while water on the inside is ［D］ and deposits sediment. This is why you often see sand ［E］ and beaches on the inside of the curve.",
