    "question": "気候変動や脱炭素の取組と自然環境の保全に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．2021年に IPCC＊1等の国際機関が合同で発表した報告書によると、気候と生物多様性は相互に関連しており、生態系の保護等のための対策は、気候変動の緩和と気候変動への適応に相乗効果をもたらすとされている。森林や藻場などによる炭素の吸収・固定機能は気候変動の緩和に寄与し、また、湿地による洪水緩和や緑地の雨水浸透の機能は気候変動への適応で重要な役割を果たす。\n\nB．昆明・モントリオール生物多様性枠組では、生物多様性の損失に最も大きな影響を与える直接要因として気候変動を挙げている。同枠組に掲げられた2050年ビジョンについては、気候変動対策も含めて同枠組の採択時点までに措置されている対策で十分達成可能であるとし、今後も同レベルの対策を行っていくことが目標として盛り込まれた。\n\nC．国立公園内において、先行して脱炭素化に取り組むエリアは、「ゼロカーボンパーク」として登録されている。このエリアでは、自然公園法の規制が特例的に緩和され、特別保護地区でも地熱発電施設の設置が認められる。令和4年3月末時点で、全ての国立公園において、その一部エリアがゼロカーボンパークに登録されている。\n\nD．絶滅危惧種の生息・生育地において、風力発電施設や太陽光発電施設の設置等が計画されており、問題となる事例が生じている。地方公共団体が制定する条例の中で、再生可能エネルギー発電施設の設置について、抑制区域や禁止区域を規定している条例の数は、FIT制度＊2の開始以降増加している。\n\n＊1 気候変動に関する政府間パネル（Intergovernmental Panel on Climate Change）\n＊2 再生可能エネルギーの固定価格買取制度（Feed-in Tariff）",
