      "イ": "国立・国定公園については、公園区域の指定後、その保護及び適正な利用の推進を図るため、公園ごとに公園計画を定めることとなっている。また、公園を取り巻く自然的・社会的条件の変化に公園計画を対応させるため、環境省は、公園計画等の見直しを進めている。当該見直しでは、現行の公園計画等の変更の必要性も含めて点検を行い、変更するに及ばない場合は点検終了とみなす。",
