    "question": "我が国の外来種問題に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．外来生物法＊1は、生態系、人の生命・身体、農林水産業に被害を及ぼす又は及ぼすおそれのあるものを特定外来生物として指定し、輸入や輸出等を禁止している。特定外来生物は、その生死にかかわらず、個体（卵、種子を含む。）及びその器官が規制の対象に含まれる。\n\nB．沖縄島及び西表島では、ハブ対策として持ち込まれたフイリマングースの分布域拡大により、在来種の分布域が縮小した。環境省等による防除事業が行われた結果、近年、沖縄島及び西表島におけるフイリマングースの生息数は、根絶できている状態となっている。\n\nC．アカミミガメとアメリカザリガニは、令和5年に「条件付特定外来生物＊2」に指定された。個体の輸入や販売、野外への放出は規制されるが、一般家庭での飼養や、頒布に当たらない個人間の無償譲渡は、当分の間、指定前と同様に自由に行うことができる。\n\nD．ヒアリは、我が国では平成29年に初めて確認され、令和5年に「要緊急対処特定外来生物」に指定された。ヒアリが存在しているおそれのある輸入品に加え、土地、車両なども検査対象となり、発見された生物がヒアリか否かを特定している間も、対象物品、車両などの移動を禁止することが可能となった。\n\n＊1 特定外来生物による生態系等に係る被害の防止に関する法律\n＊2 外来生物法に基づき特定外来生物に指定された生物のうち、通常の特定外来生物の規制の一部を、当分の間、適用除外とする（規制の一部がかからない）生物の通称",
