    "question": "我が国の野生生物の保護管理に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．鳥獣保護管理法＊では、鳥獣又は鳥類の卵について、狩猟により捕獲する場合を除き、原則としてその捕獲、殺傷又は採取が禁止されている。ただし、生態系や農林水産業に対して鳥獣による被害が生じている場合は、環境大臣又は都道府県知事の許可を受けて、鳥獣又は鳥類の卵について捕獲等をすることが認められている。\n\nB．現在の鳥獣保護管理法は、平成26年の改正時に、法目的に鳥獣の「管理」が追加され、これに伴い鳥獣の「保護」及び「管理」の定義が規定された。そのほか、都道府県知事の許可を受けた者は、鳥獣による生活環境の被害の防止のために、住居集合地域等において麻酔銃による捕獲ができることとなった。\n\nC．鳥獣保護管理法では、鳥獣の保護を図る観点から、毎年、繁殖時期である4月～6月を除外した7月～翌年3月までを狩猟期間としている。また、狩猟期間における狩猟鳥獣の捕獲は、鳥獣保護区内では禁止されていないが、狩猟鳥獣の生息数の減少が著しい場合に、自然繁殖による生息数の増加を促すために指定される休猟区では禁止されている。\n\nD．本州以南のニホンジカ及びイノシシについて、平成25年から捕獲強化が進められている。しかし、令和2年度末時点で、両種の推定個体数は増加傾向が継続しており、狩猟者数は減少傾向が継続している。このような状況を踏まえ、鳥獣の捕獲等の推進や捕獲事業者の確保のため、捕獲鳥獣の捕獲場所への放置や捕獲現場での食肉処理を認める認定鳥獣捕獲等事業者制度が導入された。\n\n＊ 鳥獣の保護及び管理並びに狩猟の適正化に関する法律",
