    "difficulty": 3,
    "question": "我が国の環境影響評価（環境アセスメント）に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．環境影響評価法では、あらゆる事業種で、規模にかかわらず、環境影響評価（環境アセスメント）を実施しなければならないとしている。環境アセスメントは、アセスメント結果の中立性を確保するため、事業を実施する事業者ではなく、環境省が指定する第三者機関が実施することとされている。\n\nB．環境アセスメントの手続のうち配慮書は、事業の位置や規模の検討段階で作成される。配慮書の作成時に、対象事業が周辺の自然環境に与える影響について検討する際は、専門的知見を有する学識者からの意見に限り、取り入れることとされている。また、環境大臣は、環境の保全に責任を持つ立場として、全ての配慮書に対して意見を述べなければならないとされている。\n\nC．環境アセスメントの評価項目や手法を選定する手続をスコーピングという。スコーピングでは、環境アセスメントの具体的な項目や調査方法等を示した計画である「環境影響評価方法書」について、地域住民や地方公共団体などから意見を聴取し、その内容を踏まえて環境アセスメントの方法を決定する。\n\nD．環境影響評価法で取り扱う環境要素としての「景観」は、「人と自然との豊かな触れ合い」の区分に含まれている。環境省の検討会を踏まえて作成された技術ガイド＊では、眺望景観だけでなく、眺望点周辺の物理的空間や場の状態に着目した三次元的景観である囲繞景観についても調査手法等を示している。\n\n＊ 環境アセスメント技術ガイド 生物の多様性・自然との触れ合い（2017年3月）",
