    "question": "我が国における代表的な都市公園に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．東京都に位置する上野恩賜公園は、太政官布達第16号により設置された公園のうち東京都内では唯一の公園である。第二次世界大戦後の政教分離政策により社寺境内地の敷地が縮小され、現在の公園区域は上野動物園の敷地のみとなっている。\n\nB．大阪府に位置する鶴見緑地は、関東大震災を契機に地震対策として計画された大緑地の一つである。その敷地は昭和45（1970）年に日本万国博覧会（大阪万博）のメイン会場となり、博覧会終了後、都市公園として開園した。\n\nC．愛知県に位置する久屋大通公園は、戦災復興事業により整備された久屋大通の中央帯に設置された公園である。公園内には、公募設置管理制度（Park-PFI）を活用して、令和2（2020）年に多くの飲食店や物品販売の店舗が開業した。\n\nD．石川県に位置する金沢城公園は、主に金沢城跡から成る都市公園であり、金沢城跡は国指定史跡にもなっている。その敷地は、第二次世界大戦の終戦後、長い間、大学として利用されていたが、大学移転により公園として整備されることとなった。公園内には、櫓や門、堀、庭園、橋など金沢城の往時の施設が整備されている。",
