    "difficulty": 3,
    "question": "我が国の緑地保全・緑化推進制度に関する記述として最も妥当なのはどれか。\n\n＊1 緑地の保全及び緑化の推進に関する基本計画\n＊2 都市再生特別措置法に基づき指定される法人\n＊3 都市緑地法第4条第2項第8号の規定に基づき定められた「緑化地域以外の区域であって重点的に緑化の推進に配慮を加えるべき地区」",
