      "イ": "緑の基本計画＊1は、緑地の保全や緑化の推進に関する施策や取組を総合的に展開することを目的とした緑に関するマスタープランであり、市町村により策定される。平成29年の都市緑地法の改正により、緑の基本計画の記載事項が拡充され、都市公園の整備及び管理の方針、都市農地の保全について記載することが可能となった。",
