      "イ": "Aは妥当だがDは誤りである。日常点検は公園管理者等が行い、異常の程度などに応じて樹木医等による診断につなげる。",
      "ウ": "Bは妥当だがCは誤りである。遊びの中で回避能力を育む危険性をリスクとし、子どもが予測しにくく事故を招くものをハザードとして除去に努める。",
