      "イ": "木材に一定の荷重をかけ続けたとき、時間の経過に伴い、木材の変形が増大する現象を応力緩和という。応力緩和は、完全弾性要素であるバネと、粘性要素であるダッシュポットを並列に結合した L-R モデルで表される。",
