    "question": "我が国の木造建築物の構法・工法に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは、「令和5年版 森林・林業白書」による。\n\nA．枠組壁工法（ツーバイフォー工法）は、柱や梁で基本的な枠組を作った後、面材で壁や床を構成するものである。大壁構造であるため防耐火性能や断熱性能を向上させることは難しいが、耐震性は高い。令和4年の木造の新設住宅着工戸数における工法別のシェアは、枠組壁工法が約6割となっている。\n\nB．木質プレハブ工法は、国土交通省告示において、「木材を使用した枠組に構造用合板その他これに類するものをあらかじめ工場で接着することにより、壁及び床版を設ける工法」と定義されている。同工法では、枠材と面材が接着剤により接着された木質接着複合パネルなどが材料として使用される。\n\nC．木造軸組工（構）法では、部材のプレカット加工があまり行われておらず、この工（構）法における令和3年のプレカット加工率は2割程度にとどまっている。一方、この工（構）法で使用される柱材や横架材の国産材の使用割合は非常に高く、大手住宅メーカーでは令和2年度の木造軸組住宅一戸当たりの国産材使用割合は9割に達している。\n\nD．丸太組構法は、丸太材又は製材を交点でかみ合わせながら1段ずつ積み上げて壁を構成するものであり、正倉院に代表される校倉造りはこの構法に含まれる。現代の丸太組構法では、一般に、壁の上下に通しボルトを入れることにより、水平荷重に対する安定性を高めている。",
