      "イ": "一般に収縮は接線方向が最も大きく、放射方向、繊維方向の順に小さい。繊維方向の収縮量を含水率1％ごとに約1％とする値は過大である。",
      "ウ": "初期は先に乾いた表層が内層に拘束されて引張りとなり、表面割れが起きやすい。後期には内層も収縮して引張りを受けるため、内部割れが生じることがある。",
