    "difficulty": 3,
    "question": "次は、木材の保存処理方法に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\nIn tropical climates and within heated buildings in temperate climates, ［A］ are typically ideal for the development of decay. High ［A］ are sometimes used in drying and treating processes to sterilize wood and kill fungi that may be present.\n\n（中略）\n\nFungi also require ［B］ and there is no practical and effective way of sealing air out of a finished wood product in order to eliminate decay. Logs in storage may be sprinkled with water or ponded to maintain high moisture contents that ［C］ fungal development. Pieces of wood completely buried in the ground or submerged in water do not have enough ［B］ for decay to occur. Wood that is buried in the soil but protrudes＊1 above the water line, such as the exposed tops of piles that support buildings in Venice, Italy or many of the buildings on the shoreline of the Great Lakes, provides a favorable location for decay to flourish＊2. Also, logs that have sunk in rivers, lakes, or ponds may be affected by anaerobic＊3 bacteria, which can ［D］ pit structures, greatly increase the permeability, and cause staining of the wood. This permeability can result in drying, treatment, and gluing problems during subsequent wood processing and also decrease aesthetic value.\n\n＊1 protrude　はみ出す\n＊2 flourish　繁茂する\n＊3 anaerobic　嫌気性",
