      "イ": "接着剤の分子量は、被着材への浸透性や凝集力に影響し、結果として接着性に影響するので、接着剤は、適度な分子量をもつことが望ましい。一般に、分子量が大きいと凝集力が大きく、強い接着力が期待できる。しかし、極端に分子量が大きいと、脆性を示しやすく接着力の低下に繋がる。",
      "ウ": "単板などの接着において、接着剤を塗布してから重ね合わせるまでの時間を閉鎖堆積時間といい、接着剤を空気にさらすことで溶剤による吸湿を促し、適度な粘着性を与えることを目的とする。閉鎖堆積時間は、木材の種類や含水率、塗布量にかかわらず、接着剤の種類ごとに決められている。",
