      "イ": "凸版印刷の一つであるオフセット印刷では、活字や版の凸部が画像部になり、インキの付着した版の凸部の上に紙を当ててインキ画像を紙に写す。また、凹版印刷は、グラビア印刷ともいわれ、親油性の画像部と親水性の非画像部を作り、親油性の画像部のみに付着したインキを紙に写す。",
      "ウ": "地合は、紙を透かして見るときの視覚的な不均一性のことをいい、一般に、パルプの繊維長が短くなるほど悪化する。針葉樹パルプは、広葉樹パルプに比べ繊維長が短いため、水懸濁液中で繊維の分散性が低くなり、フロック（凝集体）が形成されやすくなる。一方、地合の悪化により紙の強度は向上する。",
